-- S8 data manipulation (13.8 insert / 13.10 searched update / 13.7 searched delete / 13.5 select single row); self-contained on scratch tables t92_w8
-- @s08_13_8_insert_values_all_columns
DROP TABLE IF EXISTS t92_w8_c01; CREATE TABLE t92_w8_c01 (id INTEGER, a INTEGER, s VARCHAR(10), PRIMARY KEY (id)); INSERT INTO t92_w8_c01 VALUES (1, 10, 'x'); SELECT * FROM t92_w8_c01; DROP TABLE t92_w8_c01;
-- @s08_13_8_insert_column_list_reordered
DROP TABLE IF EXISTS t92_w8_c02; CREATE TABLE t92_w8_c02 (id INTEGER, a INTEGER, s VARCHAR(10), PRIMARY KEY (id)); INSERT INTO t92_w8_c02 (s, id, a) VALUES ('y', 2, 20); SELECT * FROM t92_w8_c02; DROP TABLE t92_w8_c02;
-- @s08_13_8_insert_column_list_partial
DROP TABLE IF EXISTS t92_w8_c03; CREATE TABLE t92_w8_c03 (id INTEGER, a INTEGER, s VARCHAR(10), PRIMARY KEY (id)); INSERT INTO t92_w8_c03 (id) VALUES (3); SELECT * FROM t92_w8_c03; DROP TABLE t92_w8_c03;
-- @s08_13_8_insert_null_explicit
DROP TABLE IF EXISTS t92_w8_c04; CREATE TABLE t92_w8_c04 (id INTEGER, a INTEGER, s VARCHAR(10), PRIMARY KEY (id)); INSERT INTO t92_w8_c04 VALUES (4, NULL, NULL); SELECT * FROM t92_w8_c04 WHERE a IS NULL; DROP TABLE t92_w8_c04;
-- @s08_13_8_insert_expr_values
DROP TABLE IF EXISTS t92_w8_c05; CREATE TABLE t92_w8_c05 (id INTEGER, a INTEGER, s VARCHAR(10), PRIMARY KEY (id)); INSERT INTO t92_w8_c05 VALUES (2 + 3, 10 * 4, 'z'); SELECT * FROM t92_w8_c05; DROP TABLE t92_w8_c05;
-- @s08_13_8_insert_too_many_values
DROP TABLE IF EXISTS t92_w8_c06; CREATE TABLE t92_w8_c06 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w8_c06 VALUES (1, 2, 3); SELECT * FROM t92_w8_c06; DROP TABLE t92_w8_c06;
-- @s08_13_8_insert_too_few_values_with_list
DROP TABLE IF EXISTS t92_w8_c07; CREATE TABLE t92_w8_c07 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w8_c07 (id, a) VALUES (1); SELECT * FROM t92_w8_c07; DROP TABLE t92_w8_c07;
-- @s08_13_8_insert_unknown_column
DROP TABLE IF EXISTS t92_w8_c08; CREATE TABLE t92_w8_c08 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w8_c08 (id, nosuch) VALUES (1, 2); SELECT * FROM t92_w8_c08; DROP TABLE t92_w8_c08;
-- @s08_13_8_insert_duplicate_pk
DROP TABLE IF EXISTS t92_w8_c09; CREATE TABLE t92_w8_c09 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w8_c09 VALUES (1, 1); INSERT INTO t92_w8_c09 VALUES (1, 2); SELECT * FROM t92_w8_c09; DROP TABLE t92_w8_c09;
-- @s08_13_8_insert_select
DROP TABLE IF EXISTS t92_w8_c10; CREATE TABLE t92_w8_c10 (empnum VARCHAR(3), total INTEGER, PRIMARY KEY (empnum)); INSERT INTO t92_w8_c10 SELECT empnum, SUM(hours) FROM t92_works GROUP BY empnum; SELECT * FROM t92_w8_c10; DROP TABLE t92_w8_c10;
-- @s08_13_8_insert_select_where_join
DROP TABLE IF EXISTS t92_w8_c11; CREATE TABLE t92_w8_c11 (empnum VARCHAR(3), pnum VARCHAR(3), PRIMARY KEY (empnum, pnum)); INSERT INTO t92_w8_c11 (empnum, pnum) SELECT s.empnum, p.pnum FROM t92_staff s, t92_proj p WHERE s.city = p.city; SELECT * FROM t92_w8_c11; DROP TABLE t92_w8_c11;
-- @s08_13_8_insert_select_empty
DROP TABLE IF EXISTS t92_w8_c12; CREATE TABLE t92_w8_c12 (id VARCHAR(3), PRIMARY KEY (id)); INSERT INTO t92_w8_c12 SELECT empnum FROM t92_staff WHERE grade > 100; SELECT COUNT(*) FROM t92_w8_c12; DROP TABLE t92_w8_c12;
-- @s08_13_8_insert_select_dup_pk_atomic
DROP TABLE IF EXISTS t92_w8_c13; CREATE TABLE t92_w8_c13 (g INTEGER, PRIMARY KEY (g)); INSERT INTO t92_w8_c13 SELECT grade FROM t92_staff; SELECT COUNT(*) FROM t92_w8_c13; DROP TABLE t92_w8_c13;
-- @s08_13_8_insert_select_self
DROP TABLE IF EXISTS t92_w8_c14; CREATE TABLE t92_w8_c14 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w8_c14 VALUES (1, 1); INSERT INTO t92_w8_c14 VALUES (2, 2); INSERT INTO t92_w8_c14 SELECT id + 10, a FROM t92_w8_c14; SELECT * FROM t92_w8_c14; DROP TABLE t92_w8_c14;
-- @s08_13_10_update_by_pk
DROP TABLE IF EXISTS t92_w8_c15; CREATE TABLE t92_w8_c15 (id INTEGER, a INTEGER, s VARCHAR(10), PRIMARY KEY (id)); INSERT INTO t92_w8_c15 VALUES (1, 1, 'a'); INSERT INTO t92_w8_c15 VALUES (2, 2, 'b'); UPDATE t92_w8_c15 SET a = 100 WHERE id = 1; SELECT * FROM t92_w8_c15; DROP TABLE t92_w8_c15;
-- @s08_13_10_update_by_non_key
DROP TABLE IF EXISTS t92_w8_c16; CREATE TABLE t92_w8_c16 (id INTEGER, a INTEGER, s VARCHAR(10), PRIMARY KEY (id)); INSERT INTO t92_w8_c16 VALUES (1, 1, 'a'); INSERT INTO t92_w8_c16 VALUES (2, 2, 'b'); INSERT INTO t92_w8_c16 VALUES (3, 2, 'c'); UPDATE t92_w8_c16 SET s = 'two' WHERE a = 2; SELECT * FROM t92_w8_c16; DROP TABLE t92_w8_c16;
-- @s08_13_10_update_all_rows
DROP TABLE IF EXISTS t92_w8_c17; CREATE TABLE t92_w8_c17 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w8_c17 VALUES (1, 1); INSERT INTO t92_w8_c17 VALUES (2, 2); UPDATE t92_w8_c17 SET a = a * 10; SELECT * FROM t92_w8_c17; DROP TABLE t92_w8_c17;
-- @s08_13_10_update_multiple_columns
DROP TABLE IF EXISTS t92_w8_c18; CREATE TABLE t92_w8_c18 (id INTEGER, a INTEGER, b INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w8_c18 VALUES (1, 1, 2); UPDATE t92_w8_c18 SET a = b, b = a WHERE id = 1; SELECT * FROM t92_w8_c18; DROP TABLE t92_w8_c18;
-- @s08_13_10_update_set_null
DROP TABLE IF EXISTS t92_w8_c19; CREATE TABLE t92_w8_c19 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w8_c19 VALUES (1, 1); UPDATE t92_w8_c19 SET a = NULL WHERE id = 1; SELECT * FROM t92_w8_c19; DROP TABLE t92_w8_c19;
-- @s08_13_10_update_where_subquery
DROP TABLE IF EXISTS t92_w8_c20; CREATE TABLE t92_w8_c20 (empnum VARCHAR(3), bonus INTEGER, PRIMARY KEY (empnum)); INSERT INTO t92_w8_c20 SELECT empnum, 0 FROM t92_staff; UPDATE t92_w8_c20 SET bonus = 1 WHERE empnum IN (SELECT empnum FROM t92_works WHERE hours >= 80); SELECT * FROM t92_w8_c20; DROP TABLE t92_w8_c20;
-- @s08_13_10_update_where_correlated
DROP TABLE IF EXISTS t92_w8_c21; CREATE TABLE t92_w8_c21 (empnum VARCHAR(3), total INTEGER, PRIMARY KEY (empnum)); INSERT INTO t92_w8_c21 SELECT empnum, 0 FROM t92_staff; UPDATE t92_w8_c21 SET total = 1 WHERE EXISTS (SELECT * FROM t92_works w WHERE w.empnum = t92_w8_c21.empnum AND w.pnum = 'P2'); SELECT * FROM t92_w8_c21; DROP TABLE t92_w8_c21;
-- @s08_13_10_update_self_referencing_where
DROP TABLE IF EXISTS t92_w8_c22; CREATE TABLE t92_w8_c22 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w8_c22 VALUES (1, 1); INSERT INTO t92_w8_c22 VALUES (2, 5); INSERT INTO t92_w8_c22 VALUES (3, 9); UPDATE t92_w8_c22 SET a = a + 10 WHERE a < (SELECT AVG(a) FROM t92_w8_c22) + 1; SELECT * FROM t92_w8_c22; DROP TABLE t92_w8_c22;
-- @s08_13_10_update_halloween
DROP TABLE IF EXISTS t92_w8_c23; CREATE TABLE t92_w8_c23 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w8_c23 VALUES (1, 1); INSERT INTO t92_w8_c23 VALUES (2, 2); INSERT INTO t92_w8_c23 VALUES (3, 3); UPDATE t92_w8_c23 SET a = a + 1 WHERE a >= 1; SELECT * FROM t92_w8_c23; DROP TABLE t92_w8_c23;
-- @s08_13_10_update_no_rows
DROP TABLE IF EXISTS t92_w8_c24; CREATE TABLE t92_w8_c24 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w8_c24 VALUES (1, 1); UPDATE t92_w8_c24 SET a = 9 WHERE id = 99; SELECT * FROM t92_w8_c24; DROP TABLE t92_w8_c24;
-- @s08_13_10_update_statement_atomic_on_error
DROP TABLE IF EXISTS t92_w8_c25; CREATE TABLE t92_w8_c25 (id INTEGER, a INTEGER, b INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w8_c25 VALUES (1, 10, 1); INSERT INTO t92_w8_c25 VALUES (2, 10, 0); INSERT INTO t92_w8_c25 VALUES (3, 10, 1); UPDATE t92_w8_c25 SET a = a / b; SELECT * FROM t92_w8_c25; DROP TABLE t92_w8_c25;
-- @s08_13_10_update_overflow_atomic
DROP TABLE IF EXISTS t92_w8_c26; CREATE TABLE t92_w8_c26 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w8_c26 VALUES (1, 1); INSERT INTO t92_w8_c26 VALUES (2, 2147483647); UPDATE t92_w8_c26 SET a = a + 1; SELECT * FROM t92_w8_c26; DROP TABLE t92_w8_c26;
-- @s08_13_10_update_unknown_column
DROP TABLE IF EXISTS t92_w8_c27; CREATE TABLE t92_w8_c27 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w8_c27 VALUES (1, 1); UPDATE t92_w8_c27 SET nosuch = 1; SELECT * FROM t92_w8_c27; DROP TABLE t92_w8_c27;
-- @s08_13_10_update_pk_column
DROP TABLE IF EXISTS t92_w8_c28; CREATE TABLE t92_w8_c28 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w8_c28 VALUES (1, 1); UPDATE t92_w8_c28 SET id = 2 WHERE id = 1; SELECT * FROM t92_w8_c28; DROP TABLE t92_w8_c28;
-- @s08_13_7_delete_by_pk
DROP TABLE IF EXISTS t92_w8_c29; CREATE TABLE t92_w8_c29 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w8_c29 VALUES (1, 1); INSERT INTO t92_w8_c29 VALUES (2, 2); DELETE FROM t92_w8_c29 WHERE id = 1; SELECT * FROM t92_w8_c29; DROP TABLE t92_w8_c29;
-- @s08_13_7_delete_by_non_key
DROP TABLE IF EXISTS t92_w8_c30; CREATE TABLE t92_w8_c30 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w8_c30 VALUES (1, 1); INSERT INTO t92_w8_c30 VALUES (2, 2); INSERT INTO t92_w8_c30 VALUES (3, 2); DELETE FROM t92_w8_c30 WHERE a = 2; SELECT * FROM t92_w8_c30; DROP TABLE t92_w8_c30;
-- @s08_13_7_delete_all
DROP TABLE IF EXISTS t92_w8_c31; CREATE TABLE t92_w8_c31 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w8_c31 VALUES (1, 1); INSERT INTO t92_w8_c31 VALUES (2, 2); DELETE FROM t92_w8_c31; SELECT COUNT(*) FROM t92_w8_c31; DROP TABLE t92_w8_c31;
-- @s08_13_7_delete_where_subquery
DROP TABLE IF EXISTS t92_w8_c32; CREATE TABLE t92_w8_c32 (empnum VARCHAR(3), PRIMARY KEY (empnum)); INSERT INTO t92_w8_c32 SELECT empnum FROM t92_staff; DELETE FROM t92_w8_c32 WHERE empnum NOT IN (SELECT empnum FROM t92_works); SELECT * FROM t92_w8_c32; DROP TABLE t92_w8_c32;
-- @s08_13_7_delete_self_referencing
DROP TABLE IF EXISTS t92_w8_c33; CREATE TABLE t92_w8_c33 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w8_c33 VALUES (1, 1); INSERT INTO t92_w8_c33 VALUES (2, 5); INSERT INTO t92_w8_c33 VALUES (3, 9); DELETE FROM t92_w8_c33 WHERE a > (SELECT AVG(a) FROM t92_w8_c33); SELECT * FROM t92_w8_c33; DROP TABLE t92_w8_c33;
-- @s08_13_7_delete_where_null
DROP TABLE IF EXISTS t92_w8_c34; CREATE TABLE t92_w8_c34 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w8_c34 VALUES (1, NULL); INSERT INTO t92_w8_c34 VALUES (2, 2); DELETE FROM t92_w8_c34 WHERE a <> 2; SELECT * FROM t92_w8_c34; DROP TABLE t92_w8_c34;
-- @s08_13_7_delete_no_rows
DROP TABLE IF EXISTS t92_w8_c35; CREATE TABLE t92_w8_c35 (id INTEGER, a INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w8_c35 VALUES (1, 1); DELETE FROM t92_w8_c35 WHERE a = 99; SELECT * FROM t92_w8_c35; DROP TABLE t92_w8_c35;
-- @s08_13_5_select_into_like_scalar
SELECT empname FROM t92_staff WHERE empnum = 'E3';
-- @s08_case_only_differing_text_keys
DROP TABLE IF EXISTS t92_w8_c37; CREATE TABLE t92_w8_c37 (k VARCHAR(5), v INTEGER, PRIMARY KEY (k)); INSERT INTO t92_w8_c37 VALUES ('a', 1); INSERT INTO t92_w8_c37 VALUES ('A', 2); SELECT * FROM t92_w8_c37; DROP TABLE t92_w8_c37;
-- @s08_case_only_update_wrong_row
DROP TABLE IF EXISTS t92_w8_c38; CREATE TABLE t92_w8_c38 (k VARCHAR(5), v INTEGER, PRIMARY KEY (k)); INSERT INTO t92_w8_c38 VALUES ('a', 1); UPDATE t92_w8_c38 SET v = 99 WHERE k = 'A'; DELETE FROM t92_w8_c38 WHERE k = 'Á'; SELECT * FROM t92_w8_c38; DROP TABLE t92_w8_c38;
-- @s08_case_only_get_by_pk
DROP TABLE IF EXISTS t92_w8_c39; CREATE TABLE t92_w8_c39 (k VARCHAR(5), v INTEGER, PRIMARY KEY (k)); INSERT INTO t92_w8_c39 VALUES ('a', 1); SELECT * FROM t92_w8_c39 WHERE k = 'A'; SELECT * FROM t92_w8_c39 WHERE k = 'a '; DROP TABLE t92_w8_c39;
